window.AerQr = (function () {
    const EXP = new Uint8Array(512);
    const LOG = new Uint8Array(256);
    for (let x = 1, i = 0; i < 255; i++) {
        EXP[i] = x;
        LOG[x] = i;
        x = (x << 1) ^ (x & 0x80 ? 0x11d : 0);
    }
    for (let i = 255; i < 512; i++) EXP[i] = EXP[i - 255];

    const ECC_PER_BLOCK = {
        L: [-1, 7, 10, 15, 20, 26, 18, 20, 24, 30, 18, 20, 24, 26, 30, 22, 24, 28, 30, 28, 28],
        M: [-1, 10, 16, 26, 18, 24, 16, 18, 22, 22, 26, 30, 22, 22, 24, 24, 28, 28, 26, 26, 26],
        Q: [-1, 13, 22, 18, 26, 18, 24, 18, 22, 20, 24, 28, 26, 24, 20, 30, 24, 28, 28, 26, 30],
        H: [-1, 17, 28, 22, 16, 22, 28, 26, 26, 24, 28, 24, 28, 22, 24, 24, 30, 28, 28, 26, 28]
    };
    const BLOCK_COUNT = {
        L: [-1, 1, 1, 1, 1, 1, 2, 2, 2, 2, 4, 4, 4, 4, 4, 6, 6, 6, 6, 7, 8],
        M: [-1, 1, 1, 1, 2, 2, 4, 4, 4, 5, 5, 5, 8, 9, 9, 10, 10, 11, 13, 14, 16],
        Q: [-1, 1, 1, 2, 2, 4, 4, 6, 6, 8, 8, 8, 10, 12, 16, 12, 17, 16, 18, 21, 20],
        H: [-1, 1, 1, 2, 4, 4, 4, 5, 6, 8, 8, 11, 11, 16, 16, 18, 16, 19, 21, 25, 25]
    };
    
    const ECC_FORMAT = { L: 1, M: 0, Q: 3, H: 2 };
    const MAX_VERSION = 20;

    function rawModules(ver) {
        let num = (16 * ver + 128) * ver + 64;
        if (ver >= 2) {
            const align = Math.floor(ver / 7) + 2;
            num -= (25 * align - 10) * align - 55;
            if (ver >= 7) num -= 36;
        }
        return num;
    }

    function capacityBits(ver, ecc) {
        return rawModules(ver) - ECC_PER_BLOCK[ecc][ver] * BLOCK_COUNT[ecc][ver] * 8;
    }

    function gfMul(a, b) {
        return (a === 0 || b === 0) ? 0 : EXP[LOG[a] + LOG[b]];
    }

    function rsDivisor(degree) {
        const res = new Uint8Array(degree);
        res[degree - 1] = 1;
        let root = 1;
        for (let i = 0; i < degree; i++) {
            for (let j = 0; j < degree; j++) {
                res[j] = gfMul(res[j], root);
                if (j + 1 < degree) res[j] ^= res[j + 1];
            }
            root = gfMul(root, 2);
        }
        return res;
    }

    function rsRemainder(data, divisor) {
        const res = new Uint8Array(divisor.length);
        for (const b of data) {
            const factor = b ^ res[0];
            res.copyWithin(0, 1);
            res[res.length - 1] = 0;
            for (let i = 0; i < res.length; i++) res[i] ^= gfMul(divisor[i], factor);
        }
        return res;
    }

    function toBytes(text) {
        const list = Array.from(new TextEncoder().encode(text));
        return Uint8Array.from(list);
    }

    function dataCodewords(text, ver, ecc) {
        const bytes = toBytes(text);
        const cap = capacityBits(ver, ecc);
        const bits = [];
        const push = (val, len) => {
            for (let i = len - 1; i >= 0; i--) bits.push((val >>> i) & 1);
        };
        push(4, 4);
        push(bytes.length, ver < 10 ? 8 : 16);
        for (const b of bytes) push(b, 8);
        push(0, Math.min(4, cap - bits.length));
        push(0, (8 - bits.length % 8) % 8);
        for (let pad = 0xec; bits.length < cap; pad ^= 0xec ^ 0x11) push(pad, 8);
        const out = new Uint8Array(cap / 8);
        bits.forEach((v, i) => { if (v) out[i >>> 3] |= 0x80 >>> (i & 7); });
        return out;
    }

    function addEcc(data, ver, ecc) {
        const numBlocks = BLOCK_COUNT[ecc][ver];
        const eccLen = ECC_PER_BLOCK[ecc][ver];
        const rawCw = Math.floor(rawModules(ver) / 8);
        const numShort = numBlocks - rawCw % numBlocks;
        const shortLen = Math.floor(rawCw / numBlocks);
        const divisor = rsDivisor(eccLen);
        const blocks = [];
        for (let i = 0, k = 0; i < numBlocks; i++) {
            const take = shortLen - eccLen + (i < numShort ? 0 : 1);
            const dat = data.slice(k, k + take);
            k += take;
            const block = Array.from(dat);
            if (i < numShort) block.push(0);
            blocks.push(block.concat(Array.from(rsRemainder(dat, divisor))));
        }
        const out = [];
        for (let i = 0; i < blocks[0].length; i++) {
            blocks.forEach((blk, j) => {
                if (i !== shortLen - eccLen || j >= numShort) out.push(blk[i]);
            });
        }
        return out;
    }

    function alignPositions(ver) {
        if (ver === 1) return [];
        const num = Math.floor(ver / 7) + 2;
        const step = ver === 32 ? 26 : Math.ceil((ver * 4 + 4) / (num * 2 - 2)) * 2;
        const size = ver * 4 + 17;
        const pos = [6];
        for (let p = size - 7; pos.length < num; p -= step) pos.splice(1, 0, p);
        return pos;
    }

    function makeMatrix(text, ecc, wantMask) {
        const level = ECC_PER_BLOCK[ecc] ? ecc : 'M';
        let ver = 1;
        const bytes = toBytes(text);
        while (ver <= MAX_VERSION && (4 + (ver < 10 ? 8 : 16) + bytes.length * 8) > capacityBits(ver, level)) ver++;
        if (ver > MAX_VERSION) return null;

        const size = ver * 4 + 17;
        const mod = [], func = [];
        for (let i = 0; i < size; i++) {
            mod.push(new Array(size).fill(false));
            func.push(new Array(size).fill(false));
        }
        const setFunc = (x, y, dark) => {
            if (x < 0 || y < 0 || x >= size || y >= size) return;
            mod[y][x] = dark;
            func[y][x] = true;
        };
        const drawFinder = (cx, cy) => {
            for (let dy = -4; dy <= 4; dy++) {
                for (let dx = -4; dx <= 4; dx++) {
                    const dist = Math.max(Math.abs(dx), Math.abs(dy));
                    setFunc(cx + dx, cy + dy, dist !== 2 && dist !== 4);
                }
            }
        };
        const drawAlign = (cx, cy) => {
            for (let dy = -2; dy <= 2; dy++) {
                for (let dx = -2; dx <= 2; dx++) {
                    setFunc(cx + dx, cy + dy, Math.max(Math.abs(dx), Math.abs(dy)) !== 1);
                }
            }
        };
        const drawFormat = (mask) => {
            const data = ECC_FORMAT[level] << 3 | mask;
            let rem = data;
            for (let i = 0; i < 10; i++) rem = (rem << 1) ^ ((rem >>> 9) * 0x537);
            const bits = ((data << 10) | rem) ^ 0x5412;
            for (let i = 0; i <= 5; i++) setFunc(8, i, ((bits >>> i) & 1) !== 0);
            setFunc(8, 7, ((bits >>> 6) & 1) !== 0);
            setFunc(8, 8, ((bits >>> 7) & 1) !== 0);
            setFunc(7, 8, ((bits >>> 8) & 1) !== 0);
            for (let i = 9; i < 15; i++) setFunc(14 - i, 8, ((bits >>> i) & 1) !== 0);
            for (let i = 0; i < 8; i++) setFunc(size - 1 - i, 8, ((bits >>> i) & 1) !== 0);
            for (let i = 8; i < 15; i++) setFunc(8, size - 15 + i, ((bits >>> i) & 1) !== 0);
            setFunc(8, size - 8, true);
        };

        for (let i = 0; i < size; i++) {
            setFunc(6, i, i % 2 === 0);
            setFunc(i, 6, i % 2 === 0);
        }
        drawFinder(3, 3);
        drawFinder(size - 4, 3);
        drawFinder(3, size - 4);
        const aligns = alignPositions(ver);
        aligns.forEach((ax, i) => aligns.forEach((ay, j) => {
            const corner = (i === 0 && j === 0) || (i === 0 && j === aligns.length - 1) || (i === aligns.length - 1 && j === 0);
            if (!corner) drawAlign(ax, ay);
        }));
        drawFormat(0);
        if (ver >= 7) {
            let rem = ver;
            for (let i = 0; i < 12; i++) rem = (rem << 1) ^ ((rem >>> 11) * 0x1f25);
            const bits = (ver << 12) | rem;
            for (let i = 0; i < 18; i++) {
                const dark = ((bits >>> i) & 1) !== 0;
                setFunc(size - 11 + i % 3, Math.floor(i / 3), dark);
                setFunc(Math.floor(i / 3), size - 11 + i % 3, dark);
            }
        }

        const cw = addEcc(dataCodewords(text, ver, level), ver, level);
        const bits = [];
        cw.forEach(b => { for (let i = 7; i >= 0; i--) bits.push((b >>> i) & 1); });
        let idx = 0, upward = true;
        for (let right = size - 1; right >= 1; right -= 2) {
            if (right === 6) right = 5;
            for (let vert = 0; vert < size; vert++) {
                const y = upward ? size - 1 - vert : vert;
                for (const x of [right, right - 1]) {
                    if (func[y][x]) continue;
                    mod[y][x] = idx < bits.length && bits[idx] === 1;
                    idx++;
                }
            }
            upward = !upward;
        }

        const applyMask = (mask) => {
            for (let y = 0; y < size; y++) {
                for (let x = 0; x < size; x++) {
                    if (func[y][x]) continue;
                    let invert = false;
                    if (mask === 0) invert = (x + y) % 2 === 0;
                    else if (mask === 1) invert = y % 2 === 0;
                    else if (mask === 2) invert = x % 3 === 0;
                    else if (mask === 3) invert = (x + y) % 3 === 0;
                    else if (mask === 4) invert = (Math.floor(x / 3) + Math.floor(y / 2)) % 2 === 0;
                    else if (mask === 5) invert = x * y % 2 + x * y % 3 === 0;
                    else if (mask === 6) invert = (x * y % 2 + x * y % 3) % 2 === 0;
                    else invert = ((x + y) % 2 + x * y % 3) % 2 === 0;
                    if (invert) mod[y][x] = !mod[y][x];
                }
            }
        };

        const penalty = () => {
            let score = 0;
            const runScore = (len) => len >= 5 ? 3 + len - 5 : 0;
            for (let y = 0; y < size; y++) {
                let run = 1;
                for (let x = 1; x < size; x++) {
                    if (mod[y][x] === mod[y][x - 1]) run++;
                    else { score += runScore(run); run = 1; }
                }
                score += runScore(run);
            }
            for (let x = 0; x < size; x++) {
                let run = 1;
                for (let y = 1; y < size; y++) {
                    if (mod[y][x] === mod[y - 1][x]) run++;
                    else { score += runScore(run); run = 1; }
                }
                score += runScore(run);
            }
            for (let y = 0; y < size - 1; y++) {
                for (let x = 0; x < size - 1; x++) {
                    const c = mod[y][x];
                    if (c === mod[y][x + 1] && c === mod[y + 1][x] && c === mod[y + 1][x + 1]) score += 3;
                }
            }
            const finderLike = (win) => {
                let pat = 0, units = 0;
                win.forEach((c, i) => {
                    if (i === 0 || c === win[i - 1]) units++;
                    else { pat = (pat << units) + (win[i - 1] ? 1 : 0) * Math.pow(10, units - 1); units = 1; }
                });
                return pat;
            };
            const hasFinder = (arr) => {
                for (let i = 0; i + 6 < arr.length; i++) {
                    const w = arr.slice(i, i + 7);
                    const pat = w.map(v => v ? 1 : 0).join('');
                    if (pat === '1011101') {
                        const before = arr.slice(Math.max(0, i - 4), i);
                        const after = arr.slice(i + 7, i + 11);
                        const quietBefore = before.length === 4 && before.every(v => !v);
                        const quietAfter = after.length === 4 && after.every(v => !v);
                        if (quietBefore || quietAfter) return 40;
                    }
                }
                return 0;
            };
            for (let y = 0; y < size; y++) score += hasFinder(mod[y]);
            for (let x = 0; x < size; x++) score += hasFinder(mod.map(row => row[x]));
            let dark = 0;
            for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) if (mod[y][x]) dark++;
            const total = size * size;
            score += Math.floor(Math.abs(dark * 20 - total * 10) / total) * 10;
            return score;
        };

        let bestMask = wantMask;
        if (wantMask === undefined || wantMask === null) {
            let best = Infinity;
            for (let m = 0; m < 8; m++) {
                applyMask(m);
                drawFormat(m);
                const p = penalty();
                if (p < best) { best = p; bestMask = m; }
                applyMask(m);
            }
        }
        applyMask(bestMask);
        drawFormat(bestMask);
        return { size: size, modules: mod, version: ver, mask: bestMask };
    }

    function draw(canvas, text, opts) {
        const o = opts || {};
        const ecc = o.ecc || 'H';
        const quiet = o.quiet === undefined ? 4 : o.quiet;
        const px = o.pixel || 6;
        const data = makeMatrix(text, ecc, o.mask);
        if (!data) return null;
        const side = (data.size + quiet * 2) * px;
        canvas.width = side;
        canvas.height = side;
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = o.light || '#ffffff';
        ctx.fillRect(0, 0, side, side);
        ctx.fillStyle = o.dark || '#000000';
        for (let y = 0; y < data.size; y++) {
            for (let x = 0; x < data.size; x++) {
                if (data.modules[y][x]) ctx.fillRect((x + quiet) * px, (y + quiet) * px, px, px);
            }
        }
        if (o.logo) {
            const bits = Math.max(3, Math.round(data.size * 0.24));
            const box = bits * px;
            const at = Math.round((side - box) / 2);
            const pad = Math.round(px * 0.9);
            ctx.fillStyle = o.light || '#ffffff';
            ctx.beginPath();
            const r = box * 0.18;
            ctx.roundRect(at - pad, at - pad, box + pad * 2, box + pad * 2, r);
            ctx.fill();
            return new Promise((resolve) => {
                const img = new Image();
                img.onload = () => { ctx.drawImage(img, at, at, box, box); resolve(data); };
                img.onerror = () => resolve(data);
                img.src = o.logo;
            });
        }
        return data;
    }

    return { makeMatrix: makeMatrix, draw: draw };
})();
